cards.content:
{% macro city(name, w, key) %}{% set f = states('input_text.kindle_forecast_' ~ key) | from_json(default={}) %}<h3>{{ name }}</h3><h4>{{ f.hi | default('–') }}° / {{ f.lo | default('–') }}°</h4><p>{{ state_translated(w) }}</p><p>🌧️ {{ f.rain | default('–') }}%</p>{% endmacro %}
{% set b = states('input_text.kindle_battery') | from_json(default={}) %}
<h1>{{ now().strftime('%-I:%M %p') }}</h1>
<h2>{{ now().strftime('%A, %B %-d') }}</h2>
<table><tr><td>{{ city('San Francisco', 'weather.forecast_san_francisco', 'san_francisco') }}</td><td>{{ city('Walnut Creek', 'weather.forecast_castle', 'walnut_creek') }}</td></tr></table>
{% set t = states.sensor.bart_walnut_creek_next_to_sfo %}{% if t and t.state | is_number %}{% set m = t.state | int %}<h5>NEXT TRAIN: SFO</h5><p class="train">Departs: {{ (t.last_reported + timedelta(minutes=m)) | as_local | as_timestamp | timestamp_custom('%-I:%M %p') }} ({{ 'leaving now' if m == 0 else 'in ' ~ m ~ ' min' }})</p>{% endif %}
{% set q = states('input_text.kindle_question') %}{% if q not in ['unknown', 'unavailable', ''] %}<h5>THIS OR THAT</h5><p>{{ q }}</p>{% endif %}
<h6>{% if b.level is defined %}{{ '⚡' if b.charging else '🔋' }} {{ b.level }}% · {% endif %}Updated {{ now().strftime('%-I:%M %p') }}</h6>

style.ha-markdown$:
h1, h2, h3, h4, h6, p { margin: 0; color: #000; }
h1 { font-size: 5.5em; line-height: 1.05; text-align: center; white-space: nowrap; margin-top: 8px; }
h2 { font-size: 1.5em; text-align: center; margin: 4px 0 16px; }
table { width: 100%; border-collapse: separate !important; border-spacing: 8px; margin: 0 -8px; width: calc(100% + 16px); }
td { width: 50%; vertical-align: top; border: 1px solid #999 !important; border-radius: 12px; padding: 12px 16px; }
td h3 { font-size: 1.4em; margin-bottom: 10px; }
td h4 { font-size: 2.2em; margin-bottom: 8px; }
td p { font-size: 1.2em; font-weight: bold; margin-bottom: 6px; }
h6 { position: absolute; left: 8px; bottom: 8px; font-size: 1.1em; }
h5 { font-size: 1.4em; margin: 12px 0 4px; letter-spacing: 0.05em; }
h5 + p { font-size: 1.6em; font-weight: bold; margin: 0; line-height: 1.2; }
p + h5 { margin-top: 24px; }  /* gap between the train and the question */
